@Bean
SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.authorizeHttpRequests(auth -> auth
            .requestMatchers("/health", "/static/**").permitAll()  // explicit public set
            .requestMatchers("/admin/**").hasRole("ADMIN")         // explicit grant
            .anyRequest().denyAll());                              // nothing else is reachable
    return http.build();
}
// Jakarta method security: @DenyAll means no role may invoke the method;
// @RolesAllowed("ADMIN") is the explicit grant the container enforces.
